inline bool registerRiveBindingNatives()
{
    return wasm_runtime_register_natives(
               "rive_rt_v1",
               kRtNatives,
               sizeof(kRtNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_data_v1",
               kDataNatives,
               sizeof(kDataNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_artboard_v1",
               kArtboardNatives,
               sizeof(kArtboardNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_path_v1",
               kPathNatives,
               sizeof(kPathNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_paint_v1",
               kPaintNatives,
               sizeof(kPaintNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_gpu_v1",
               kGpuNatives,
               sizeof(kGpuNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_buffer_v1",
               kBufferNatives,
               sizeof(kBufferNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_blob_v1",
               kBlobNatives,
               sizeof(kBlobNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_image_v1",
               kImageNatives,
               sizeof(kImageNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_shader_v1",
               kShaderNatives,
               sizeof(kShaderNatives) / sizeof(NativeSymbol)) &&
           wasm_runtime_register_natives(
               "rive_renderer_v1",
               kRendererNatives,
               sizeof(kRendererNatives) / sizeof(NativeSymbol));
}
